        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else None
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else None

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    if hp <= 2 or no_water >= 2:
        emergency = 66
        if highest_prev is not None:
            emergency = max(emergency, highest_prev + 2)
        return min(budget, emergency)

    if hp <= 4 or no_water >= 1:
        urgent = 48
        if highest_prev is not None and highest_prev < 62:
            urgent = max(urgent, highest_prev + 1.5)
        elif highest_prev is not None and highest_prev >= 62:
            urgent = 63
        if supply_tight:
            urgent += 4
        return min(budget, urgent)

    base = 0
    if supply_loose:
        base = 16
    elif supply_tight:
        base = 31
    else:
        base = 23

    if desperate_count >= 2:
        base += 5
    elif desperate_count == 1:
        base += 2

    if rich_count >= 2:
        base += 3

    if highest_prev is None:
        if day <= 2:
            return min(budget, base)
        return min(budget, base + 2)

    if highest_prev >= 63:
        if hp >= 6 and no_water == 0:
            return min(budget, 14 if supply_loose else 18)
        return min(budget, 61)

    if highest_prev >= 48:
        target = highest_prev + 1.5
        if supply_loose:
            target -= 4
        return min(budget, max(base, target))

    target = max(base, (avg_prev if avg_prev is not None else base) + 2)
    if supply_loose:
        target -= 2
    return min(budget, target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))

    # React to yesterday only if traces exist; otherwise default strategy.
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', True):
            alive_opps.append((opp_id, opp))

    # Default: conservative bid that still contests.
    # Supply in [15,25] implies 1-1.9 of WATER_REQ per unit; bid moderate.
    base_bid = DAILY_SALARY * 0.55

    # Survival adjustments
    if hp <= 2.0:
        base_bid = DAILY_SALARY * 0.90
    elif hp <= 3.0:
        base_bid = DAILY_SALARY * 0.70

    # Budget constraint
    if budget <= DAILY_SALARY * 0.3:
        base_bid = min(budget, DAILY_SALARY * 0.35)

    # Use yesterday's opponent behavior if available
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If opponents were already spending heavily, we slightly undercut unless we're in danger.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if hp > 3.0:
                base_bid = min(budget, max(DAILY_SALARY * 0.25, highest_prev_bid * 0.85))
            else:
                base_bid = min(budget, max(DAILY_SALARY * 0.80, highest_prev_bid * 0.95))
        else:
            # If they were moderate, match the pressure with a small premium.
            base_bid = min(budget, max(base_bid, highest_prev_bid + 1.5))

    # Supply-aware tweak: when supply is closer to MIN_SUPPLY, contest a bit more.
    if supply <= (MIN_SUPPLY + 1.0):
        base_bid = max(base_bid, DAILY_SALARY * 0.60)
    elif supply >= (MAX_SUPPLY - 1.0):
        base_bid = min(base_bid, DAILY_SALARY * 0.50)

    # Final clamp: bid cannot exceed budget.
    bid = min(budget, base_bid)
    if bid < 0:
        bid = 0.0
    return bid
